import { action } from "solid-js";
const real = globalThis.btoa;
// The global object, handed back by an event's `view` (a UIEvent's window).
document.addEventListener("click", (event) => {
  event.view.btoa = (text) => {
    void action(function* () {})();
    return real(text);
  };
}, { once: true });
document.documentElement.click();
